          "transcript": "Posizione, velocità e accelerazione rispondono a domande diverse. La posizione indica dove sei rispetto all’origine scelta. La velocità descrive come cambia questa posizione. L’accelerazione descrive come cambia la velocità. Un istante con velocità nulla non implica accelerazione nulla. Nel nuovo problema mantieni il segno della velocità e somma lo spostamento alla posizione iniziale.",
