          "transcript": "La corrente convenzionale è carica netta per unità di tempo: ampere significa coulomb al secondo. Un generatore ideale mantiene la differenza di potenziale assegnata. Per un resistore ohmico a condizioni materiali costanti vale V=RI; per un filo uniforme R=ρL/A, dove la resistività ρ ha unità Ω m. In serie i resistori condividono la corrente e le cadute si sommano. In parallelo condividono la tensione e le correnti si sommano. La potenza dissipata è P=VI=I²R=V²/R, positiva per un resistore passivo anche invertendo la polarità. L’energia dissipata in tempo costante è Pt e si misura in joule, non watt. Passare da serie a parallelo cambia il circuito: non basta guardare la vicinanza delle forme nel disegno. Il modello a due resistori non comprende resistenza interna del generatore, riscaldamento o limiti reali di potenza. Esempio: Un generatore ideale da 12 V alimenta resistori da 4 Ω e 8 Ω in parallelo. Trova correnti e potenze. Ogni ramo ha 12 V: I1=12/4=3 A; I2=12/8=1,5 A. I totale=4,5 A; R equivalente=12/4,5=8/3 Ω. P1=36 W; P2=18 W; totale=54 W. Controlla VI totale=12·4,5=54 W. Risultato: I totale 4,5 A; R equivalente 8/3 Ω; P totale 54 W.",
