          "audioTranscript": "La frequenza conta le oscillazioni in un secondo. La lunghezza d’onda misura la distanza fra due punti che oscillano nella stessa fase. A velocità di propagazione fissata, aumentare la frequenza riduce la lunghezza d’onda. Non confondere una fotografia della forma nello spazio con l’oscillazione nel tempo in un punto. Nel nuovo mezzo riparti dalla nuova velocità e dalla nuova frequenza.",
